#!/usr/bin/env python3
"""Render S22 pages and compatibility card from measured JSON. Never promote."""
from html import escape as esc
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render_sources():
    docs = ROOT / 'docs'
    c = json.loads((docs / 's22/run-card.json').read_text())
    audit = json.loads((docs / 's22/nine-site-audit.json').read_text())
    if c['verdict'] != 'negative' or c['ok_to_submit'] is not False:
        raise ValueError('S22 pages only publish an explicitly negative research result')
    a, h = c['artifact'], c['holdout']
    compat = dict(c)
    compat.update(result='negative', submission_ready=False, verdict=dict(promote=False, OK_TO_SUBMIT='NO'),
                  canonical_evidence='s22/run-card.json', raster_path=a['tif'],
                  raster=dict(path=a['tif'], zip=a['zip'], sha256=c['raster_sha256'], zip_sha256=a['zip_sha256']))
    (docs / 'run-card-S22-OMTJ.json').write_text(json.dumps(compat, indent=2, allow_nan=False) + '\n')
    tif, zip_path = a['tif'].removeprefix('docs/'), a['zip'].removeprefix('docs/')
    dup = c['correlation_overlap_vs_registry']['final_dot_checks']['duplicate']
    ci = f"[{h['ci95'][0]:.6f}, {h['ci95'][1]:.6f}]"
    status = f'''<section class="hero" data-submission-ready="false">
<div class="eyebrow">GEMSDOE91 / S22 · evidence checked 26 October 2026</div>
<h1>A new raster. A clear stop.</h1>
<p class="lede">OMTJ tests magnetic texture boundaries against gravity structure. It generated new prediction bytes, but failed your strict uniqueness gate. <strong>There is no approved competition submission from this run.</strong></p>
<div class="status"><strong>OK TO DOWNLOAD: YES — RESEARCH ONLY</strong><strong class="no">OK TO SUBMIT: NO — NOT OK TO SUBMIT</strong></div>
<p><a class="button" download href="{esc(tif)}">Download new research TIFF ↓</a> <a class="button secondary" download href="{esc(zip_path)}">Single-TIFF ZIP</a></p>
<p class="small">Not a copied submission; not certified protocol-unique. Do not spend a weekly slot on this file. The duplicate stop is automatic, not a request for a human inspector.</p>
<div class="metrics"><div><span>HOLDOUT-DTI</span><b>{h['dti']:.6f}</b><small>95% CI {ci}</small></div><div><span>Literal 3-pixel overlap</span><b>{dup['overlap_within_3px']:.2%}</b><small>FAIL · required ≤70%</small></div><div><span>Local numeric / grid checks</span><b>PASS</b><small>All finite [0,1] · one float32 band</small></div><div><span>Experiments / slots used</span><b>1 / 0</b><small>Stopped at duplicate witness</small></div></div>
<p class="small">{esc(h['evaluator_version'])} · {h['withheld_positive_pixels']:,} withheld positive pixels · 1,000-draw 20 km block bootstrap. This interval is conditional holdout uncertainty, <strong>not a leaderboard estimate</strong>.</p>
<details><summary>File identity, unique name and short note</summary><p><b>Name:</b> <code>{esc(c['submission_name'])}</code></p><p><b>Note ({len(c['submission_note'])}/140):</b> <code>{esc(c['submission_note'])}</code></p><p><b>SHA256:</b> <code>{c['raster_sha256']}</code></p><p>37,654 positive pixels; EPSG:32611; 3,730 rows × 3,292 columns. Sample-matched affine (100, 0, 243350, 0, -100, 4508550). Zero NaN/Inf; zero nodata encoding outside footprint. Local checks do not establish organizer acceptance.</p></details>
</section>'''
    recommendations = {
        'GEMSDOE24': 'Historical dense dotted baseline. Its highest claimed result fails the geometric uniqueness rule; do not re-upload.',
        'GEMSDOE25': 'Support is identical to GEMSDOE30 despite different file bytes. A new name or encoding cannot make it unique.',
        'GEMSDOE27': 'Highest claimed historical result is the topo-gap-closure file. Other H29 research is a separate artifact, not proof this leader is unique.',
        'GEMSDOE28': 'Audit uses the actual h36-1 rung30 file named with the highest claim, not a similarly named h27-4 predecessor.',
        'GEMSDOE30': 'Same positive support as GEMSDOE25. Educational comparison only; do not resubmit.',
        'GEMSDOE31': 'Solo-d28 predecessor is strongly shared with GEMSDOE32 and the rest of the family. Outside NaN encoding is not a novelty change.',
        'GEMSDOE32': 'Highest historical claim in these nine sites. Keep as a research anchor, not a fresh submission; the claimed result has no receipt here.',
        'GEMSDOE33': 'Audit uses the prompt-named analog-tip-stepover raster, not a smaller pruned cousin. It fails the peer-overlap gate.',
        'GEMSDOE36': 'Audit uses the 38,854-dot Anderson artifact, not a 40,199-dot ancestor. It overlaps the historical family too strongly.'}
    rows = []
    sections = []
    for r in sorted(audit['sites'], key=lambda r: -r['claimed_historical_value']):
        witness = r['max_overlap_vs_other_eight']
        rows.append(f'''<tr><th scope="row"><a href="executive-summary.html#{r['site']}">{r['site']}</a></th><td><a href="{esc(r['source_url'])}">{esc(r['filename'])}</a><small>Historical reference only · do not submit</small></td><td>{r['claimed_historical_value']:.4f}<small>USER CLAIM — not ORGANIZER-CONFIRMED</small></td><td>Unavailable<small>No calibrated estimate or receipt</small></td><td class="fail">NO<small>{witness['overlap_within_3px']:.2%} vs {witness['reference_site']} within 3 px</small></td></tr>''')
        sections.append(f'''<article id="{r['site']}"><h3>{r['site']}</h3><p>{esc(recommendations[r['site']])}</p><p class="small">Measured support: {r['positive_pixels']:,} pixels. All cells finite: {r['validator']['all_cells_finite']}. In-footprint finite and grid-match checks: PASS. <a href="{esc(r['blob_api_url'])}">Immutable blob evidence</a> · SHA256 <code>{r['sha256']}</code>.</p></article>''')
    table = f'''<section id="nine-sites"><h2>Which file is best across the nine sites?</h2><p><strong>By your unverified historical claims: GEMSDOE32. By the full submission gates: none is cleared.</strong> S22 re-hashed each exact leader and checked all 72 directed peer comparisons. All nine fail the 70% overlap limit against another site. No historical file is recommended as a new submission.</p>
<div class="table-scroll"><table><caption>Exact historical leaders · repository snapshots: {esc(audit['as_of_utc'][:10])}. Claims are preserved, not promoted to measured scores.</caption><thead><tr><th>Site</th><th>File / evidence (not an upload recommendation)</th><th>Reported historical claim</th><th>Estimated leaderboard score</th><th>Unique among the other eight?</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>
<p><a href="s22/nine-site-audit.json">Full pairwise measurements &amp; SHA256s</a> · <a href="s22/current-page-inventory.json">Current nine-site source inventory</a></p></section>'''
    research = '''<section id="research"><h2>Why the historical leader may work — and what we cannot infer</h2><p>Spacing can retain coverage while removing redundant false positives; catalogue-collar pruning may remove low-credit dots. This is a plausible metric explanation, <strong>not proof of what caused a hidden score</strong>. The exact metric distinguishes truth-side credit from prediction-side credit. A score and dot count alone do not identify hidden truth prevalence.</p><p>Four ranked, catalogue-independent hypotheses were preregistered. We tested one: a signed third-moment magnetic texture boundary aligned with a gravity gradient. Unfaulted volcanic contacts and survey-line artifacts can mimic it. This is fault-localization research, not confirmed geothermal-vent discovery.</p><p><a href="s22/preregistration.md">Four hypotheses and frozen protocol</a> · <a href="s22/research-and-limitations.md">Scientific analysis, official sources &amp; limitations</a></p></section>'''
    gates = f'''<section id="gates"><h2>Automated gates, without visual inspection</h2><ul><li><b>Local format: PASS.</b> TIFF and ZIP re-read by the shared writer; all pixels finite in [0,1]; correct CRS, shape and affine.</li><li><b>Leakage canary: PASS.</b> Seven raw/derived features × four folds; maximum symmetric AUC {c['leakage_canary']['max_symmetric_auc']:.6f} ≤0.90. This is a canary, not proof of geological validity.</li><li><b>Pre-placement surface:</b> {c['correlation_overlap_vs_registry']['surface_checked']} unique-byte registry rasters checked; max positive Spearman {c['correlation_overlap_vs_registry']['surface_max_rank_correlation']:.6f} ≤0.90.</li><li><b>Final dots: FAIL.</b> Stopped at <code>{esc(dup['path'])}</code>, overlap {dup['overlap_within_3px']:.2%}. No dense-raster exception. Remaining final-dot comparisons were not run.</li><li><b>Scientific promotion: NOT ESTABLISHED.</b> Poor holdout result, no matched incumbent rerun, two frozen references missing and no organizer-complete registry.</li><li><b>Weekly selector: NOT AUTHORIZED.</b> Zero slots spent. Current remaining quota unavailable.</li></ul><p><a href="s22/run-card.json">Canonical JSON run card</a> · <a href="run-card-S22-OMTJ.json">Current-pointer compatibility card</a> · <a href="s22/holdout.json">Holdout and confidence interval</a> · <a href="s22/writer-receipt.json">Validator receipt</a> · <a href="s22/final-dot-checks.json">Duplicate stop witness</a></p></section>'''
    guide = '''<section id="how-to-submit"><h2>Exactly how a future approved submission is entered</h2><p class="warning"><strong>Do not upload the S22 file.</strong> The download above is a negative research deliverable, not an approval to upload that file. These steps apply only to a future file that passes every gate and receives separate selector authorization.</p><ol><li>Run <code>python generate_submission.py --with-data</code> to verify the current downloadable bytes. A format PASS alone is not permission to submit.</li><li>Require complete registry clearance, fold-honest improvement over a matched incumbent, and a current quota/selector record. The official rules specify up to three submissions per week; current remaining allowance must come from the authenticated submission page.</li><li>Download the approved <code>.tif</code>, or its ZIP containing exactly one TIFF. Do not upload this report or a JSON card.</li><li>On DrivenData, choose <b>New submission → File to submit</b>, select the approved raster, and paste its short identifying note into <b>Note (optional)</b>.</li><li>After processing, retain the organizer submission ID, receipt, score, timestamp and exact uploaded SHA256. Only then label that result ORGANIZER-CONFIRMED.</li><li>Before the competition deadline, select one final submission for both rounds. Preserve reproducible code, data licenses and the required generative-AI disclosure.</li></ol><p>The official page says data outside bounds is null/NaN; the repository writer uses all-finite zeros outside the footprint to avoid numeric rejection. This discrepancy is disclosed, not silently treated as organizer acceptance.</p><p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/#submission-format">Official format</a> · <a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Official rules</a> · <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">Competition</a></p></section>'''
    archive = '''<section id="archive"><h2>Evidence &amp; history</h2><p><a href="s21-pdwc-executive-summary.html">S21 PDWC (historical, negative)</a> · <a href="s20-rhtw-exec-src.html">S20 RHTW (historical)</a> · <a href="archive-results.html">Earlier experiments</a> · <a href="download-audit.html">All-download technical audit</a> · <a href="fleet-audit.json">Scheduled source-inventory feed</a> · <a href="s22/review.md">Three-pass review</a></p><p><a href="REVIEW-ACTIVE-E649E460-20261025.md">Historical safety review</a> · <a href="run-card-E649E460-20261025.json">Historical review card</a> · <a href="s17-lftg.html">S17-LFTG research audit</a> · <a href="s17-cpad.html">S17-CPAD research audit</a></p><p class="small">A source feed is not a score feed. Public leaderboard observed on 26 October: 0.4437 at rank 1 (xiaofanhu), not a receipt for our raster. <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard</a>. Bulk external-data access and authenticated receipts remain limited; current cached inputs were restored automatically and hash-checked.</p></section>'''
    style = '''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f3f5f2;color:#1d302b;font:16px/1.65 system-ui,sans-serif}main,header,footer{max-width:1180px;margin:auto;padding:24px}header{display:flex;gap:24px;justify-content:space-between;flex-wrap:wrap;border-bottom:1px solid #d6dfd9}nav{display:flex;gap:22px;flex-wrap:wrap}a{color:#17604a;text-underline-offset:3px}h1{font-size:clamp(32px,5vw,56px);line-height:1.1;letter-spacing:-2px;margin:20px 0}h2{font-size:27px;line-height:1.3}h3{font-size:21px}section{background:white;border:1px solid #d6dfd9;border-radius:12px;padding:30px;margin-bottom:24px}.hero{border-top:5px solid #b97428}.eyebrow,span{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#526a61}.lede{max-width:850px;font-size:19px}.status{display:flex;gap:15px;flex-wrap:wrap;font-size:13px}.status strong{background:#e6efe9;border-radius:4px;padding:8px 12px}.status .no,.warning{background:#fff1df;color:#7f4312}.button{display:inline-block;background:#194d3e;color:white;text-decoration:none;padding:12px 18px;border-radius:6px;font-weight:650;margin:5px 8px 5px 0}.secondary{background:#e8eeea;color:#194d3e}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:18px;margin:28px 0}.metrics div{border-left:2px solid #d6dfd9;padding:0 14px}.metrics b{display:block;font-size:29px}.small,small{font-size:13px;color:#526a61}small{display:block}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}caption{text-align:left;padding:14px 0;color:#526a61}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #dde4df;padding:14px 12px}thead{background:#eef3ef}td:nth-child(2){min-width:220px;max-width:370px;overflow-wrap:anywhere}.fail{color:#923e19;font-weight:700}code{overflow-wrap:anywhere;font-size:12px}details{border-top:1px solid #d6dfd9;padding-top:14px}summary{cursor:pointer;font-weight:600}article{border-top:1px solid #d6dfd9;padding:10px 0}li{margin:10px 0}.warning{padding:15px;border-radius:6px}footer{font-size:13px;color:#526a61}@media(max-width:600px){main,header,footer{padding:16px}section{padding:20px}th,td{padding:10px 8px}}'''
    def shell(title, body):
        return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · GEMSDOE91</title><style>{style}</style></head><body><header><b>GEMS / RESEARCH OPERATIONS</b><nav aria-label="Main navigation"><a href="index.html">Download &amp; status</a><a href="executive-summary.html">Executive summary</a><a href="executive-summary.html#how-to-submit">Submission guide</a></nav></header><main id="main">{body}</main><footer>Maximize P(Win) · Own the Outcome · Negative results protect scarce submission slots.</footer></body></html>\n'''
    (docs / 's22-index-src.html').write_text(shell('Current download and automated verdict', status + table + research + gates + archive))
    (docs / 's22-exec-src.html').write_text(shell('Nine-site executive summary and submission guide', status + table + '<section><h2>Executive summary for every site</h2>' + ''.join(sections) + '</section>' + research + gates + guide + archive))
    # Dedicated names survive later changes to the current front door.
    (docs / 's22-executive-summary.html').write_text((docs / 's22-exec-src.html').read_text())


if __name__ == '__main__':
    render_sources()
